 ) d
 WHERE d.age<=p_window_days AND (d.snapshot_day IS NULL
  OR (d.age<=7) OR (d.age<=30 AND d.snapshot_day<=today-7) OR (d.snapshot_day<=today-14))
 LIMIT p_limit;
 RETURN out;
END $function$;
